"""Migration of the Meridian CRM credit-hold nightly sweep."""

from decimal import Decimal, InvalidOperation
from fractions import Fraction
from typing import Any


def _number(value: Any) -> Fraction:
    """Return the legacy NVL-style numeric value, with exact decimal semantics."""
    if value is None:
        return Fraction(0)

    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Fraction(0)

    if isinstance(value, bool):
        return Fraction(int(value))

    try:
        if isinstance(value, int):
            return Fraction(value)
        if isinstance(value, Fraction):
            return value
        if isinstance(value, Decimal):
            return Fraction(value)
        # str(float_value) intentionally avoids importing binary float artifacts.
        return Fraction(Decimal(str(value)))
    except (InvalidOperation, ValueError, TypeError, ZeroDivisionError):
        return Fraction(0)


def _primary_key(value: Any) -> tuple[int, Any]:
    """Provide a deterministic ascending key while preserving string key ordering."""
    if isinstance(value, (int, float, Decimal, Fraction)) and not isinstance(value, bool):
        return (0, _number(value))
    if isinstance(value, str):
        return (1, value)
    if value is None:
        return (2, "")
    return (3, repr(value))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Apply the nightly credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indexes.sort(key=lambda index: _primary_key(new_accounts[index].get("ACCT_ID")))

    for index in eligible_indexes:
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")

        exposure = Fraction(0)
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _number(order.get("TOT_AMT"))

        credit_limit = _number(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        # Compare against 80% by cross multiplication to retain exact decimals.
        if exposure * 10 <= credit_limit * 8 and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
